#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Обработка кнопок//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {   COLORREF mTxt;// текст   COLORREF mBkg;// фон   char szKlapanName[128];   double StateValue[5];   char   StateText[5][256];  } Queue_KlapanStateFromValue;// Функция отображенияint PaintKlapanStateFromValue(DefinePaint)  {	  QueueP(Queue_KlapanStateFromValue);	  //	  CShKlapan* sh = (CShKlapan*)PipeSh;      double dValue=sh->Vent;      int ii=0;      for(; ii< _countof(p->StateValue); ii++)        if(p->StateValue[ii]==DBL_MIN) break;        else if(dValue <= p->StateValue[ii])               break; //нашли - рисуем      if((ii>0) || (p->StateValue[ii]!=DBL_MIN))      {        if ( p->mBkg != 0xffffffff )          {          CMyBrush brush(hDC, p->mBkg);          brush.Rect( p->mRect );          }        CMyFont font( hDC, NULL, p->mTxt );        font.DrawS( p->mRect, p->StateText[ii], DT_CENTER );      }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddKlapanStateFromValue(DefineTegs){  //  AddQueueEx(Queue_KlapanStateFromValue);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintKlapanStateFromValue;  //p->nNumber=-1;  p->mTxt = 0;  p->mBkg = RGB(115,115,115);  p->szKlapanName[0]=0;  char szSFcom[64] = "";  memset(&p->StateText, 0, sizeof(p->StateText));  for(int ii=0; ii< _countof(p->StateValue); ii++)    p->StateValue[ii]=DBL_MIN;  //  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },    { 'A', "textcolor", &p->mTxt     },    { 'A', "bkgcolor", &p->mBkg     },    { 'S', "suffcommon", szSFcom, 63 },    { 'S', "StateText1", &p->StateText[0], 255 },    { 'S', "StateText2", &p->StateText[1], 255 },    { 'S', "StateText3", &p->StateText[2], 255 },    { 'S', "StateText4", &p->StateText[3], 255 },    { 'S', "StateText5", &p->StateText[4], 255 },    { 'D', "StateValue1", &p->StateValue[0]},    { 'D', "StateValue2", &p->StateValue[1]},        { 'D', "StateValue3", &p->StateValue[2]},        { 'D', "StateValue4", &p->StateValue[3]},    { 'D', "StateValue5", &p->StateValue[4]},    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (teg[0].value)  {      strcpy_s(p->szKlapanName, teg[0].value);      if(*szSFcom)      {//добавляется суффикс к переменной       strcat_s( p->szKlapanName, szSFcom);      }	  p->nNumber=def.AddKindEx( id_Klapan, p->szKlapanName );  }}//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~